// n8n Function node: "Validate" (ephemeral retrieval)
const src = ($json && $json.body) ? $json.body : $json;
const query           = src.query;
const tenant_id       = src.tenant_id;
const conversation_id = src.conversation_id;
const rawMax          = src.max_chunks;
const history         = src.conversation_history;

// Required (fail-closed; tenant_id is the isolation gate)
const required = { query, tenant_id, conversation_id };
for (const [k, v] of Object.entries(required)) {
  if (v === undefined || v === null || (typeof v === 'string' && v.trim() === '')) {
    throw new Error(`Missing required field: ${k}`);   // -> 422
  }
}

let max_chunks = 5;
if (rawMax !== undefined && rawMax !== null && rawMax !== '') {
  const n = Number(rawMax);
  if (!Number.isInteger(n)) throw new Error(`max_chunks must be an integer: ${rawMax}`);
  if (n < 1 || n > 20) throw new Error(`max_chunks out of range [1, 20]: ${n}`);
  max_chunks = n;
}

let conversation_history = [];
if (Array.isArray(history)) {
  conversation_history = history
    .filter(m => m && typeof m === 'object' && m.role && typeof m.content === 'string')
    .slice(-10)
    .map(m => ({ role: String(m.role), content: String(m.content) }));
}

return [{ json: {
  query: String(query),
  tenant_id: String(tenant_id),
  conversation_id: String(conversation_id),
  max_chunks,
  candidate_limit: 20,
  conversation_history,
}}];

// n8n Function node: "Build embedding literal"
// Turn Voyage's float array into a pgvector string literal + assemble kNN params.
const v = $('Validate').first().json;
const cur = items[0].json;                 // Voyage response
const emb = cur && cur.data && cur.data[0] && cur.data[0].embedding;
if (!Array.isArray(emb) || emb.length !== 1024) {
  throw new Error('Bad query embedding: expected 1024 dims');   // -> 5xx (embedding)
}
return [{ json: {
  query: v.query,
  tenant_id: v.tenant_id,
  conversation_id: v.conversation_id,
  max_chunks: v.max_chunks,
  candidate_limit: v.candidate_limit,
  conversation_history: v.conversation_history,
  embedding: `[${emb.join(',')}]`,         // ::vector literal for $1
}}];

// n8n Function node: "Collect candidates"
// Postgres kNN runs with alwaysOutputData:true, so on 0 rows it emits a single
// empty item. Collapse all rows into ONE item carrying a candidates[] array
// (possibly empty). Passthrough read by node name so it survives the SQL hop.
const meta = $('Build embedding literal').first().json;
const rows = items.map(i => i.json).filter(r => r && r.id);
return [{ json: {
  query: meta.query,
  tenant_id: meta.tenant_id,
  conversation_id: meta.conversation_id,
  max_chunks: meta.max_chunks,
  conversation_history: meta.conversation_history,
  candidates: rows.map(r => ({
    id: r.id,
    content: r.content,
    source_name: r.source_name,
    chunk_index: r.chunk_index,
    score: typeof r.score === 'number' ? r.score : null,
  })),
}}];

// n8n Function node: "Build prompt"
// Reached from Rerank (true path) OR Has candidates? false (short-circuit path).
const meta = $('Collect candidates').first().json;
const candidates = meta.candidates || [];

if (!candidates.length) {
  return [{ json: { short_circuit: true, conversation_id: meta.conversation_id, query: meta.query, sources: [] } }];
}

const rr = items[0].json;
let ordered;
if (rr && Array.isArray(rr.results)) {
  ordered = rr.results
    .slice()
    .sort((a, b) => b.relevance_score - a.relevance_score)
    .slice(0, meta.max_chunks)
    .map(r => candidates[r.index] ? { ...candidates[r.index], score: r.relevance_score } : null)
    .filter(Boolean);
} else {
  ordered = candidates.slice(0, meta.max_chunks);
}

const context = ordered.map((c, n) =>
  `[${n + 1}] (source: ${c.source_name}, chunk ${c.chunk_index})\n${c.content}`
).join('\n\n');

const historyMsgs = (meta.conversation_history || []).map(m => ({ role: m.role, content: m.content }));

const systemPrompt =
`You are a grounded assistant answering ONLY from the user's uploaded session documents below.

ANSWER RULES
- Use ONLY the numbered context. Never add facts, names, dates, history, or outside knowledge that is not present in the context. If the answer is not in the context, reply exactly: "I couldn't find that in the documents you uploaded in this session."
- Be COMPLETE and EXHAUSTIVE. When the context contains a list, enumerate EVERY item in it — do not summarize, merge, paraphrase away, truncate, or use "etc." Reproduce each item faithfully.
- Preserve the document's structure: keep its headings, sub-groups (e.g. categories, sub-clauses), and ordering. Use bullet points or numbered lists that mirror the source.
- When the user asks for "all details" or about a specific section/law/clause/topic, return the FULL content of every matching chunk, organized clearly — leave nothing out.
- Cite the supporting bracket number(s) after each statement or list group, e.g. [1], [2]. If several chunks contribute, cite all of them.
- Do not editorialize, infer, or add commentary beyond what the context states.

After the answer, output a line starting with FOLLOWUPS: followed by a JSON array of exactly 3 short follow-up questions.

CONTEXT:
${context}`;

const messages = [
  { role: 'system', content: systemPrompt },
  ...historyMsgs,
  { role: 'user', content: meta.query },
];

return [{ json: {
  short_circuit: false,
  conversation_id: meta.conversation_id,
  query: meta.query,
  messages,
  sources: ordered.map((c, n) => ({
    citation: n + 1,
    chunk_text: c.content,
    source_name: c.source_name,
    chunk_index: c.chunk_index,
    score: c.score,
  })),
}}];

// n8n Function node: "Format response"
const bp = $('Build prompt').first().json;
const cur = items[0].json;

let answer, follow_up_questions;
if (bp.short_circuit) {
  answer = "I couldn't find any documents in this session to answer that. Try uploading a file first.";
  follow_up_questions = [];
} else {
  const raw = cur && cur.choices && cur.choices[0] && cur.choices[0].message
    ? (cur.choices[0].message.content || '') : '';
  const idx = raw.indexOf('FOLLOWUPS:');
  if (idx >= 0) {
    answer = raw.slice(0, idx).trim();
    try { follow_up_questions = JSON.parse(raw.slice(idx + 'FOLLOWUPS:'.length).trim()); }
    catch (e) { follow_up_questions = []; }
  } else {
    answer = raw.trim();
    follow_up_questions = [];
  }
  if (!Array.isArray(follow_up_questions)) follow_up_questions = [];
}

return [{ json: {
  answer,
  sources: (bp.sources || []).map(s => ({
    chunk_text: s.chunk_text,
    source_name: s.source_name,
    chunk_index: s.chunk_index,
    score: s.score,
  })),
  follow_up_questions,
  faithfulness: null,
  requires_clarification: false,
  conversation_id: bp.conversation_id,
  metadata: { model: 'deepseek-v4-flash', chunks_retrieved: (bp.sources || []).length },
}}];

// n8n Function node: "Format Error" (ephemeral retrieval)
const j = items[0].json || {};
const rawErr = (j && j.error && typeof j.error === 'object') ? j.error : j;
const msg =
  (rawErr && (rawErr.message || rawErr.description)) ||
  (typeof j.error === 'string' ? j.error : null) ||
  j.message ||
  'Unexpected error during ephemeral retrieval';
const msgStr = String(msg);

const RULES = [
  { re: /Missing required field/i,             phase: 'validation', node: 'Validate',                code: 422 },
  { re: /max_chunks/i,                         phase: 'validation', node: 'Validate',                code: 422 },
  { re: /Bad query embedding/i,                phase: 'embedding',  node: 'Build embedding literal',  code: 500 },
  { re: /voyage|input_type|dimension/i,        phase: 'embedding',  node: 'Embed query (Voyage)',    code: 500 },
  { re: /rerank|relevance_score|documents/i,   phase: 'rerank',     node: 'Rerank (Voyage)',         code: 500 },
  { re: /deepseek|choices|completions/i,       phase: 'generation', node: 'Generate (DeepSeek)',     code: 500 },
  { re: /SELECT|relation|column|ephemeral_chunks|vector|syntax error/i, phase: 'retrieval', node: 'pgvector kNN (top 20)', code: 500 },
];
const m = RULES.find(r => r.re.test(msgStr));
const phase = m ? m.phase : 'unknown';
const statusCode = m ? m.code : 500;
const errorType = statusCode === 422 ? 'validation' : 'runtime';
const node = m ? m.node : 'unknown';

let query = null, tenant_id = null, conversation_id = null;
try {
  const w = $('Webhook /retrieve-ephemeral').first().json;
  const b = (w && w.body) ? w.body : w;
  query = b.query || null; tenant_id = b.tenant_id || null; conversation_id = b.conversation_id || null;
} catch (e) {}

return [{ json: {
  status: 'failed', phase, node, errorType, statusCode, error: msgStr,
  query, tenant_id, conversation_id, timestamp: new Date().toISOString(),
}}];
